.page {
  min-height: 100vh;
  box-sizing: border-box;
  padding: 32px 24px;
  background: var(--g-color-base-background);
}

.form-card {
  max-width: 1100px;
  margin: 0 auto;
  padding: 28px;
}

.form-title {
  margin: 0 0 4px;
}

.form-subtitle {
  margin-bottom: 24px;
}

.editor-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  align-items: stretch;
}

@media (max-width: 800px) {
  .editor-grid {
    grid-template-columns: 1fr;
  }
}

.field-label {
  display: block;
  margin-bottom: 8px;
}

.field-hint {
  display: block;
  margin-top: 6px;
}

.preview-pane {
  border: 1px solid var(--g-color-line-generic);
  border-radius: 8px;
  padding: 16px 20px;
  background: var(--g-color-base-generic-ultralight);
  min-height: 240px;
  overflow-wrap: break-word;
}

.preview-empty {
  color: var(--g-color-text-secondary);
}

/* Rendered markdown */
.md-heading {
  margin: 16px 0 8px;
  line-height: 1.25;
}
.md-heading:first-child {
  margin-top: 0;
}
.md-p {
  margin: 8px 0;
  line-height: 1.55;
}
.md-inline-code {
  background: var(--g-color-base-misc-light);
  border-radius: 4px;
  padding: 1px 5px;
  font-size: 0.9em;
}
.md-code-block {
  background: var(--g-color-base-misc-light);
  border-radius: 8px;
  padding: 12px 16px;
  overflow-x: auto;
  font-size: 0.9em;
  line-height: 1.5;
}
.md-quote {
  margin: 8px 0;
  padding: 4px 16px;
  border-left: 4px solid var(--g-color-line-brand);
  color: var(--g-color-text-secondary);
  background: var(--g-color-base-generic-ultralight);
  border-radius: 0 8px 8px 0;
}
.md-list {
  margin: 8px 0;
  padding-left: 24px;
}
.md-hr {
  border: none;
  border-top: 1px solid var(--g-color-line-generic);
  margin: 16px 0;
}
.preview-pane a {
  color: var(--g-color-text-link);
}

